python3 -c "
import re, sys

# Find .unwrap() in non-test code
for f in __import__('glob').glob('src/**/*.rs', recursive=True):
    with open(f) as fh:
        lines = fh.readlines()
    in_test = False
    for i, line in enumerate(lines, 1):
        if '#[cfg(test)]' in line:
            in_test = True
        if in_test and line.strip().startswith('mod ') and '{' in line:
            # Simple heuristic - track test module depth
            pass
        if '.unwrap()' in line and not in_test:
            print(f'{f}:{i}: {line.rstrip()}')
" 2>&1 | head -80

