24	}
25	
26	impl InitCommand {
27	    /// Create a new init command.
28	    pub fn new(project_root: &Path, args: InitArgs) -> Self {
29	        Self {
30	            project_root: project_root.to_path_buf(),
31	            args,
32	        }
33	    }
34	
35	    /// Get the project root path.
36	    pub fn project_root(&self) -> &Path {
37	        &self.project_root
38	    }
39	
40	    /// Get the command arguments.
41	    pub fn args(&self) -> &InitArgs {
42	        &self.args
43	    }
44	
45	    /// Check if config already exists.
46	    fn config_exists(&self) -> bool {
47	        self.project_root.join(".bivvy/config.yml").exists()
48	    }
49	
50	    /// Resolve the absolute path to the user's local schema file.
51	    ///
52	    /// Returns `~/.bivvy/schema.json` if the home directory is discoverable.
53	    /// `main` runs `ensure_global_config()` before any command dispatches,
54	    /// so this file is guaranteed to exist by the time `init` is invoked.
55	    fn schema_path() -> Option<PathBuf> {
56	        crate::sys::home_dir().map(|h| h.join(".bivvy/schema.json"))
57	    }
58	
59	    /// Create configuration content from selected steps with template info.
60	    ///
61	    /// When `schema_path` is `Some`, prepends a `# yaml-language-server:`
62	    /// directive so editors with the YAML language server pick up completion
63	    /// and validation against the locally installed schema.
64	    fn create_config(
65	        &self,
66	        steps: &[(&str, Option<&Template>)],
67	        schema_path: Option<&Path>,
68	    ) -> String {
69	        let project_name = self
70	            .project_root
71	            .file_name()
72	            .and_then(|n| n.to_str())
73	            .unwrap_or("MyApp");
74	
75	        let mut config = String::new();
76	
77	        if let Some(path) = schema_path {
78	            config.push_str(&format!(
79	                "# yaml-language-server: $schema={}\n",
80	                path.display()
81	            ));
82	        }
83	
