265	            assert!(pinned.bar_clone().is_some());
266	        }
267	        // Bar is dropped — finish_and_clear has been called.
268	    }
269	
270	    #[test]
271	    fn transient_region_sets_max_lines() {
272	        let surface = TerminalSurface::hidden();
273	        let bar = ProgressBar::new_spinner();
274	        let region = surface.transient_above_pinned(bar, 4);
275	        assert_eq!(region.max_lines(), 4);
276	    }
