305	        // via running a panicking closure.
306	        let surface = TerminalSurface::hidden();
307	        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
308	            surface.with_cursor_freed(|| panic!("boom"));
309	        }));
310	        assert!(outcome.is_err());
311	        // After the panic, the surface is still usable.
312	        surface.println("post-panic");
313	    }
