261	/// Execute a command with streaming output.
262	pub fn execute_streaming(
263	    command: &str,
264	    options: &CommandOptions,
265	    callback: OutputCallback,
266	) -> Result<CommandResult> {
267	    let start = Instant::now();
268	
269	    let shell = detect_shell();
270	    let shell_flag = shell_flag(&shell);
271	
272	    let mut cmd = Command::new(&shell);
273	    cmd.arg(shell_flag);
274	    cmd.arg(command);
275	
276	    // Run the child in bivvy's own process group. An earlier attempt
277	    // moved the child into its own group via `Command::process_group(0)`
278	    // (commit a19bdae) to keep zsh's job control from reclaiming the
279	    // foreground when the child exits. That fix exposed a worse hang:
280	    // commands whose process trees touch the controlling terminal
281	    // (notably `cargo test`, where libtest or its child binaries make
282	    // a transient `tcsetpgrp` call and then the temporary foreground
283	    // pgid dies) leave every member of the now-background child group
284	    // permanently SIGTTOU-stopped. Sharing bivvy's pgroup keeps the
285	    // child in the foreground for the duration of its run, and the
286	    // `claim_foreground` call after wait still re-asserts ownership
287	    // for the zsh edge case.
288	
289	    if let Some(cwd) = &options.cwd {
290	        cmd.current_dir(cwd);
291	    }
292	
293	    for (key, value) in &options.env {
294	        cmd.env(key, value);
295	    }
296	
297	    if options.stdin_null {
298	        cmd.stdin(Stdio::null());
299	    }
300	
301	    cmd.stdout(Stdio::piped());
302	    cmd.stderr(Stdio::piped());
303	
304	    let mut child = cmd.spawn().map_err(|_| BivvyError::CommandFailed {
305	        command: command.to_string(),
306	        code: None,
307	    })?;
308	
309	    let stdout = child.stdout.take().unwrap();
310	    let stderr = child.stderr.take().unwrap();
311	
312	    let (tx, rx) = mpsc::channel();
313	    let tx_stdout = tx.clone();
314	    let tx_stderr = tx;
315	
316	    // Spawn threads to read stdout and stderr
317	    let stdout_handle = thread::spawn(move || {
318	        let reader = BufReader::new(stdout);
319	        let mut output = String::new();
320	        for line in reader.lines().map_while(std::result::Result::ok) {
321	            output.push_str(&line);
322	            output.push('\n');
323	            let _ = tx_stdout.send(OutputLine::Stdout(line));
324	        }
325	        output
326	    });
327	
328	    let stderr_handle = thread::spawn(move || {
329	        let reader = BufReader::new(stderr);
330	        let mut output = String::new();
331	        for line in reader.lines().map_while(std::result::Result::ok) {
332	            output.push_str(&line);
333	            output.push('\n');
334	            let _ = tx_stderr.send(OutputLine::Stderr(line));
335	        }
336	        output
337	    });
338	
339	    // Process output through sink
340	    for line in rx {
341	        callback.write_line(line);
342	    }
343	
344	    let stdout_output = stdout_handle.join().unwrap_or_default();
345	    let stderr_output = stderr_handle.join().unwrap_or_default();
346	
347	    let status = child.wait().map_err(|_| BivvyError::CommandFailed {
348	        command: command.to_string(),
349	        code: None,
350	    })?;
351	
352	    // Re-claim foreground after the child's process group exits.
353	    #[cfg(unix)]
354	    claim_foreground();
355	
356	    let duration = start.elapsed();
357	
358	    if status.success() {
359	        Ok(CommandResult::success(
360	            stdout_output,
361	            stderr_output,
362	            duration,
363	        ))
364	    } else {
365	        Ok(CommandResult::failure(
366	            status.code(),
367	            stdout_output,
368	            stderr_output,
369	            duration,
370	        ))
371	    }
372	}
