900	/// Map a [`SkipReason`] (produced by the decision engine) to the typed
901	/// terminal [`StepOutcomeKind`] it represents.
902	///
903	/// `SkipReason::AutoSatisfied` is handled by `handle_auto_satisfied` and
904	/// never reaches the generic skip fall-through, but we map it here for
905	/// completeness so a future caller cannot misroute it.
906	fn skip_reason_to_outcome(reason: &SkipReason) -> StepOutcomeKind {
907	    match reason {
908	        SkipReason::CheckPassed | SkipReason::Satisfied | SkipReason::AutoSatisfied => {
909	            StepOutcomeKind::Satisfied
910	        }
911	        SkipReason::UserDeclined | SkipReason::SensitiveDeclined => StepOutcomeKind::Declined,
912	        SkipReason::RequirementNotMet => StepOutcomeKind::Blocked,
913	    }
914	}
