132	pub(crate) fn read_secure() -> io::Result<String> {
133	    let mut input = Input::buffered()?;
134	
135	    let mut termios = mem::MaybeUninit::uninit();
136	    c_result(|| unsafe { libc::tcgetattr(input.as_raw_fd(), termios.as_mut_ptr()) })?;
137	    let mut termios = unsafe { termios.assume_init() };
138	    let original = termios;
139	    termios.c_lflag &= !libc::ECHO;
140	    c_result(|| unsafe { libc::tcsetattr(input.as_raw_fd(), libc::TCSAFLUSH, &termios) })?;
141	    let mut rv = String::new();
142	
143	    let read_rv = input.read_line(&mut rv);
144	
145	    c_result(|| unsafe { libc::tcsetattr(input.as_raw_fd(), libc::TCSAFLUSH, &original) })?;
146	
147	    read_rv.map(|_| {
148	        let len = rv.trim_end_matches(&['\r', '\n'][..]).len();
149	        rv.truncate(len);
150	        rv
151	    })
152	}
