230	// Similar to libc::read. Read count bytes into slice buf from descriptor fd.
231	// If successful, return the number of bytes read.
232	// Will return an error if nothing was read, i.e when called at end of file.
233	fn read_bytes(fd: RawFd, buf: &mut [u8], count: u8) -> io::Result<u8> {
234	    let read = unsafe { libc::read(fd, buf.as_mut_ptr() as *mut _, count as usize) };
235	    if read < 0 {
236	        Err(io::Error::last_os_error())
237	    } else if read == 0 {
238	        Err(io::Error::new(
239	            io::ErrorKind::UnexpectedEof,
240	            "Reached end of file",
241	        ))
242	    } else if buf[0] == b'\x03' {
243	        Err(io::Error::new(
244	            io::ErrorKind::Interrupted,
245	            "read interrupted",
246	        ))
247	    } else {
248	        Ok(read as u8)
249	    }
250	}
