        if term.is_term() {
            return;
        }
        let prompt = make_prompt("input_eof", PromptType::Input, None);
        let result = prompt_input(&prompt, &term);
        assert!(result.is_err());
    }

    #[test]
    fn prompt_select_returns_default_on_eof() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
