    // Ctrl+D / EOF handling tests
    // -----------------------------------------------------------------------

    #[test]
    fn is_eof_detects_unexpected_eof() {
        let err = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "end of file");
        assert!(is_eof(&err));
    }

    #[test]
    fn is_eof_rejects_other_errors() {
        let err = std::io::Error::new(std::io::ErrorKind::NotFound, "not found");
        assert!(!is_eof(&err));
    }

    #[test]
    fn ctrl_d_byte_is_recognized() {
        // Ctrl+D in raw mode sends byte 0x04. Verify the constant we
        // use in match arms is correct.
        assert_eq!(CTRL_D, '\x04');
    }

    #[test]
    fn prompt_confirm_returns_default_on_eof() {
        // Simulate EOF by using a non-TTY term. On non-TTY, read_key
        // returns Key::Unknown which dialoguer can't handle, producing
        // an error. With our EOF handling, this should fall back to the
        // default value instead of panicking.
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let prompt = make_prompt("confirm_eof", PromptType::Confirm, Some("true"));
        let result = prompt_confirm(&prompt, &term);
        // Should return the default (true) rather than an error.
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_bool(), Some(true));
    }

    #[test]
    fn prompt_confirm_returns_default_false_on_eof() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let prompt = make_prompt("confirm_eof", PromptType::Confirm, Some("false"));
        let result = prompt_confirm(&prompt, &term);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_bool(), Some(false));
    }

    #[test]
    fn prompt_input_returns_default_on_eof() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let prompt = make_prompt("input_eof", PromptType::Input, Some("fallback"));
        let result = prompt_input(&prompt, &term);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_string(), "fallback");
    }

    #[test]
    fn prompt_input_errors_on_eof_without_default() {
        let term = Term::stdout();
        if term.is_term() {
