        }
        let prompt = make_prompt("input_eof", PromptType::Input, None);
        let result = prompt_input(&prompt, &term);
        assert!(result.is_err());
    }

    #[test]
    fn prompt_select_returns_default_on_eof() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let options = vec![
            PromptOption {
                label: "A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "B".to_string(),
                value: "b".to_string(),
            },
            PromptOption {
                label: "C".to_string(),
                value: "c".to_string(),
            },
        ];
        let prompt = make_prompt(
            "select_eof",
            PromptType::Select {
                options: options.clone(),
            },
            Some("b"),
        );
        let result = prompt_select(&prompt, &options, &term);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_string(), "b");
    }

    #[test]
    fn prompt_multiselect_returns_defaults_on_eof() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let options = vec![
            PromptOption {
                label: "X".to_string(),
                value: "x".to_string(),
            },
            PromptOption {
                label: "Y".to_string(),
                value: "y".to_string(),
