        assert!(result.is_err());
    }

    #[test]
    fn prompt_select_returns_default_on_eof() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let options = vec![
            PromptOption {
                label: "A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "B".to_string(),
