            PromptOption {
                label: "C".to_string(),
                value: "c".to_string(),
            },
        ];
        let prompt = make_prompt(
            "select_eof",
            PromptType::Select {
                options: options.clone(),
            },
            Some("b"),
        );
        let result = prompt_select(&prompt, &options, &term);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_string(), "b");
    }

    #[test]
    fn prompt_multiselect_returns_defaults_on_eof() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let options = vec![
            PromptOption {
                label: "X".to_string(),
                value: "x".to_string(),
            },
            PromptOption {
                label: "Y".to_string(),
                value: "y".to_string(),
            },
        ];
        let prompt = make_prompt(
            "multi_eof",
            PromptType::MultiSelect {
                options: options.clone(),
            },
            Some("x,y"),
        );
        let result = prompt_multiselect(&prompt, &options, &term);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_string(), "x,y");
    }
}

