        ];
        let prompt = make_prompt(
            "rerun_step",
            PromptType::Select {
                options: options.clone(),
            },
            Some("yes"),
        );

        // Call the REAL prompt code, not MockUI.
        // No SIGTTOU, no panic, no crash — just a clean IO error.
        let result = prompt_select(&prompt, &options, &term);
        assert!(result.is_err());
    }

