                options: options.clone(),
            },
            Some("yes"),
        );

        // Call the REAL prompt code, not MockUI.
        // No SIGTTOU, no panic, no crash — returns default on EOF.
        let result = prompt_select(&prompt, &options, &term);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_string(), "yes");
    }

