//! Interactive prompts.

use console::{style, Key, Style, Term};
use dialoguer::theme::ColorfulTheme;
use dialoguer::{Confirm, Input, MultiSelect, Select};

use crate::error::{BivvyError, Result};

use super::{Prompt, PromptOption, PromptResult, PromptType};

/// Ctrl+D byte value in raw mode.
const CTRL_D: char = '\x04';

/// Check if an IO error indicates EOF (Ctrl+D / closed stdin).
fn is_eof(err: &std::io::Error) -> bool {
    err.kind() == std::io::ErrorKind::UnexpectedEof
}

/// Check if a dialoguer error indicates EOF.
fn is_dialoguer_eof(err: &dialoguer::Error) -> bool {
    match err {
        dialoguer::Error::IO(io_err) => is_eof(io_err),
    }
}

/// Convert dialoguer errors to BivvyError.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    BivvyError::Io(e.into())
}

/// Dialoguer theme without the default yellow `?` prefix.
fn prompt_theme() -> ColorfulTheme {
    ColorfulTheme {
        prompt_prefix: style("".to_string()),
        ..ColorfulTheme::default()
    }
}

/// Check for an environment variable override for a prompt.
///
/// Users can skip any prompt by setting an env var matching the prompt key:
///   `BUMP=minor bivvy run --workflow release`
///
/// The lookup is case-insensitive on the key side: a prompt with key "bump"
/// matches env var `BUMP`, `bump`, or `Bump`.
pub(crate) fn env_override(prompt: &Prompt) -> Option<PromptResult> {
    let env_key = prompt.key.to_uppercase();
    let value = std::env::var(&env_key).ok()?;

    let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
    if is_multiselect {
        let values: Vec<String> = value.split(',').map(|s| s.trim().to_string()).collect();
        Some(PromptResult::Strings(values))
    } else {
        Some(PromptResult::String(value))
    }
}

/// Prompt the user for input.
///
/// Before showing any interactive prompt, checks for an environment variable
/// matching the prompt key (e.g., `BUMP=minor` for a prompt with key "bump").
/// This works in both interactive and non-interactive modes.
pub fn prompt_user(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    if let Some(result) = env_override(prompt) {
        return Ok(result);
    }

    match &prompt.prompt_type {
        PromptType::Confirm => prompt_confirm(prompt, term),
        PromptType::Input => prompt_input(prompt, term),
        PromptType::Select { options } => prompt_select(prompt, options, term),
        PromptType::MultiSelect { options } => prompt_multiselect(prompt, options, term),
    }
}

fn prompt_confirm(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    let default = prompt
        .default
        .as_ref()
        .map(|s| s.to_lowercase() == "true" || s == "y" || s == "yes")
        .unwrap_or(true);

    match Confirm::new()
        .with_prompt(&prompt.question)
        .default(default)
        .interact_on(term)
    {
        Ok(result) => Ok(PromptResult::Bool(result)),
        Err(e) if is_dialoguer_eof(&e) => Ok(PromptResult::Bool(default)),
        Err(e) => Err(map_dialoguer_err(e)),
    }
}

fn prompt_input(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
    let input = Input::<String>::new().with_prompt(&prompt.question);

    let result: String = if let Some(default) = &prompt.default {
        match input.default(default.clone()).interact_on(term) {
            Ok(v) => v,
            Err(e) if is_dialoguer_eof(&e) => default.clone(),
            Err(e) => return Err(map_dialoguer_err(e)),
        }
    } else {
        input.interact_on(term).map_err(map_dialoguer_err)?
    };

    Ok(PromptResult::String(result))
}

/// Dialoguer theme for general select prompts with `›`/`·` indicators.
fn select_theme() -> ColorfulTheme {
    ColorfulTheme {
        prompt_prefix: style("".to_string()),
        prompt_suffix: style("".to_string()),
        success_prefix: style("".to_string()),
        success_suffix: style("·".to_string()).for_stderr().dim(),
        active_item_prefix: style("›".to_string()).for_stderr().bold(),
        inactive_item_prefix: style("·".to_string()).for_stderr().dim(),
        active_item_style: Style::new().for_stderr().bold(),
        inactive_item_style: Style::new().for_stderr().dim(),
        values_style: Style::new().for_stderr().bold(),
        ..ColorfulTheme::default()
    }
}

/// Check if options form a yes/no pair.
fn is_yes_no(options: &[PromptOption]) -> bool {
    options.len() == 2
        && options.iter().any(|o| o.value == "yes")
        && options.iter().any(|o| o.value == "no")
}

fn prompt_select(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
    // Use custom yes/no prompt for y/n keyboard shortcut support.
    // Requires a real TTY — prompt_yes_no uses term.read_key() directly.
    // On non-TTY, fall through to dialoguer's Select.
    //
    // Terminal foreground group is claimed in main.rs via tcsetpgrp(),
    // so read_key() works even when launched via `cargo run`.
    if is_yes_no(options) && term.is_term() {
        return prompt_yes_no(prompt, options, term);
    }

    // Dumb terminals don't support cursor movement, so dialoguer's
    // clear-and-repaint cycles produce non-deterministic garbage.
    // Use a forward-only renderer instead.
    if super::is_dumb_term() && term.is_term() {
        return prompt_select_dumb(prompt, options, term);
    }

    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();

    let default_idx = prompt
        .default
        .as_ref()
        .and_then(|d| options.iter().position(|o| o.value == *d))
        .unwrap_or(0);

    let selection = match Select::with_theme(&select_theme())
        .with_prompt(&prompt.question)
        .items(&labels)
        .default(default_idx)
        .interact_on(term)
    {
        Ok(idx) => idx,
        Err(e) if is_dialoguer_eof(&e) => default_idx,
        Err(e) => return Err(map_dialoguer_err(e)),
    };

    Ok(PromptResult::String(options[selection].value.clone()))
}

/// Forward-only select prompt for dumb terminals.
///
/// Renders options once, accepts arrow keys and Enter without redrawing.
/// No cursor-movement sequences are emitted, so PTY output is deterministic.
fn prompt_select_dumb(
    prompt: &Prompt,
    options: &[PromptOption],
    term: &Term,
) -> Result<PromptResult> {
    let default_idx = prompt
        .default
        .as_ref()
        .and_then(|d| options.iter().position(|o| o.value == *d))
        .unwrap_or(0);

    let mut sel = default_idx;

    let _raw_guard = RawModeGuard::enter(term).map_err(BivvyError::Io)?;

    term.write_line(&prompt.question).map_err(BivvyError::Io)?;

    for (i, opt) in options.iter().enumerate() {
        let line = if i == sel {
            format!("  › {}", opt.label)
        } else {
            format!("  · {}", opt.label)
        };
        term.write_line(&line).map_err(BivvyError::Io)?;
    }
    term.flush().map_err(BivvyError::Io)?;

    loop {
        let key = match term.read_key() {
            Ok(k) => k,
            Err(e) if is_eof(&e) => {
                drop(_raw_guard);
                return Ok(PromptResult::String(options[sel].value.clone()));
            }
            Err(e) => return Err(BivvyError::Io(e)),
        };

        match key {
            Key::Escape | Key::Char(CTRL_D) => {
                drop(_raw_guard);
                return Ok(PromptResult::String(options[default_idx].value.clone()));
            }
            Key::Enter | Key::Char(' ') => {
                drop(_raw_guard);
                term.write_line(&format!("  › {}", options[sel].label))
                    .map_err(BivvyError::Io)?;
                return Ok(PromptResult::String(options[sel].value.clone()));
            }
            Key::ArrowDown | Key::Tab | Key::Char('j') => {
                sel = (sel + 1) % options.len();
            }
            Key::ArrowUp | Key::BackTab | Key::Char('k') => {
                sel = (sel + options.len() - 1) % options.len();
            }
            _ => {}
        }
    }
}

/// RAII guard that restores the terminal cursor when dropped.
///
/// Ensures the cursor is shown even if the process panics or is
/// interrupted (Ctrl+C) while the cursor is hidden during a prompt.
struct CursorGuard<'a> {
    term: &'a Term,
}

impl<'a> CursorGuard<'a> {
    fn new(term: &'a Term) -> std::io::Result<Self> {
        term.hide_cursor()?;
        Ok(Self { term })
    }
}

impl Drop for CursorGuard<'_> {
    fn drop(&mut self) {
        self.term.show_cursor().ok();
    }
}

/// RAII guard that sets the terminal to raw mode and restores on drop.
///
/// On macOS, characters that arrive while the terminal is in canonical
/// (cooked) mode are stored in the canonical editing buffer. When
/// `tcsetattr` switches to raw mode (ICANON off), macOS does NOT make
/// those buffered characters available for non-canonical reads — they
/// are effectively lost. This is a macOS kernel behavior difference
/// from Linux.
///
/// By setting raw mode before any prompt output, keystrokes that arrive
/// at any point during the prompt are always in the raw input queue and
/// immediately available for `read_key()`.
#[cfg(unix)]
struct RawModeGuard {
    fd: i32,
    original: libc::termios,
}

#[cfg(unix)]
impl RawModeGuard {
    fn enter(term: &Term) -> std::io::Result<Self> {
        use std::os::unix::io::AsRawFd;
        let fd = term.as_raw_fd();

        unsafe {
            let mut original = std::mem::MaybeUninit::<libc::termios>::uninit();
            if libc::tcgetattr(fd, original.as_mut_ptr()) != 0 {
                return Err(std::io::Error::last_os_error());
            }
            let original = original.assume_init();

            let mut raw = original;
            libc::cfmakeraw(&mut raw);
            // Preserve output processing so \n maps to \r\n in prompt text.
            raw.c_oflag = original.c_oflag;

            if libc::tcsetattr(fd, libc::TCSADRAIN, &raw) != 0 {
                return Err(std::io::Error::last_os_error());
            }

            Ok(Self { fd, original })
        }
    }
}

#[cfg(unix)]
impl Drop for RawModeGuard {
    fn drop(&mut self) {
        unsafe {
            libc::tcsetattr(self.fd, libc::TCSADRAIN, &self.original);
        }
    }
}

#[cfg(not(unix))]
struct RawModeGuard;

#[cfg(not(unix))]
impl RawModeGuard {
    fn enter(_term: &Term) -> std::io::Result<Self> {
        Ok(Self)
    }
}

/// Custom yes/no prompt with `›`/`·` indicators and `y`/`n` keyboard shortcuts.
///
/// Renders options below the prompt question, indented to align with
/// the step name. Supports arrow keys, j/k, Enter/Space, y/n, and Escape.
///
/// # SIGTTOU / SIGTTIN safety
///
/// This function calls `term.read_key()` directly, which:
///   - Uses `tcsetattr` to enter raw mode → triggers SIGTTOU
///   - Reads from the terminal fd → triggers SIGTTIN
///
/// When bivvy is not the terminal's foreground process group (e.g.,
/// launched via `cargo run`), zsh suspends the process with
/// "suspended (tty output)" or "suspended (tty input)".
///
/// **This function depends on signal ignores in `main.rs`.**
/// Without both `libc::signal(libc::SIGTTOU, libc::SIG_IGN)` and
/// `libc::signal(libc::SIGTTIN, libc::SIG_IGN)` in main(), calling
/// this function will crash the entire run command.
///
/// DO NOT remove the signal ignores in main.rs without also removing
/// the direct `term.read_key()` call here. See regression tests:
/// `yes_no_prompt_does_not_crash_on_non_tty` and
/// `yes_no_and_multi_option_selects_error_consistently`.
fn prompt_yes_no(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
    let dumb = super::is_dumb_term();

    let default_idx = prompt
        .default
        .as_ref()
        .and_then(|d| options.iter().position(|o| o.value == *d))
        .unwrap_or(0);

    let mut sel = default_idx;

    // Calculate indent from leading whitespace in the question text.
    // Questions are pre-indented to align with the step header above.
    // No leading whitespace and no bracket → no indent (e.g., "Run setup now?").
    let leading_ws = prompt.question.len() - prompt.question.trim_start().len();
    let pad = if leading_ws > 0 {
        " ".repeat(leading_ws)
    } else if let Some(bracket_pos) = prompt.question.find(']') {
        " ".repeat(bracket_pos + 2)
    } else {
        String::new()
    };

    let active_prefix = Style::new().bold();
    let active_style = Style::new().bold();
    let inactive_prefix = Style::new().dim();
    let inactive_style = Style::new().dim();

    // Enter raw mode BEFORE writing any prompt output. On macOS,
    // keystrokes that arrive while in canonical (cooked) mode are lost
    // when tcsetattr switches to raw mode — the canonical buffer is not
    // drained into the non-canonical read queue. By setting raw mode
    // first, any keystroke (from user or PTY test harness) lands
    // directly in the raw input queue and is immediately available.
    //
    // Guard is dropped after the selection, restoring cooked mode for
    // normal output.
    let _raw_guard = RawModeGuard::enter(term).map_err(BivvyError::Io)?;

    // Write prompt question
    term.write_line(&prompt.question).map_err(BivvyError::Io)?;

    // Hide cursor with RAII guard — cursor is restored on drop (panic, Ctrl+C, early return).
    // Dumb terminals don't support cursor visibility, so skip the CSI sequence.
    let _cursor_guard = if dumb {
        None
    } else {
        Some(CursorGuard::new(term).map_err(BivvyError::Io)?)
    };

    // Draw initial option lines
    for (i, opt) in options.iter().enumerate() {
        let line = if i == sel {
            format!(
                "{}{} {}",
                pad,
                active_prefix.apply_to("›"),
                active_style.apply_to(&opt.label)
            )
        } else {
            format!(
                "{}{} {}",
                pad,
                inactive_prefix.apply_to("·"),
                inactive_style.apply_to(&opt.label)
            )
        };
        term.write_line(&line).map_err(BivvyError::Io)?;
    }
    term.flush().map_err(BivvyError::Io)?;

    loop {
        // Read key — terminal is already in raw mode so read_key() is a
        // no-op mode switch (raw→raw). Characters are available immediately.
        let key = match term.read_key() {
            Ok(k) => k,
            Err(e) if is_eof(&e) => {
                let no_idx = options
                    .iter()
                    .position(|o| o.value == "no")
                    .unwrap_or(default_idx);
                Key::Char(if options[no_idx].value == "no" {
                    'n'
                } else {
                    ' '
                })
            }
            Err(e) => return Err(BivvyError::Io(e)),
        };

        let chosen = match key {
            Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
            Key::Char('n') | Key::Char('N') => options.iter().position(|o| o.value == "no"),
            Key::Enter | Key::Char(' ') => Some(sel),
            Key::Escape | Key::Char(CTRL_D) => {
                // Treat Escape/Ctrl+D as "no" (matching dialoguer's abort behavior).
                // Find "no" option; fall back to default if somehow absent.
                let no_idx = options
                    .iter()
                    .position(|o| o.value == "no")
                    .unwrap_or(default_idx);
                Some(no_idx)
            }
            Key::ArrowDown | Key::Tab | Key::Char('j') => {
                sel = (sel + 1) % options.len();
                None
            }
            Key::ArrowUp | Key::BackTab | Key::Char('k') => {
                sel = (sel + options.len() - 1) % options.len();
                None
            }
            _ => None,
        };

        if let Some(idx) = chosen {
            // Drop raw mode before writing answer text — restores output
            // processing (OPOST) so \n maps to \r\n correctly.
            drop(_raw_guard);

            let (icon, answer_label) = if options[idx].value == "yes" {
                (Style::new().green().apply_to("✓"), "Yes")
            } else {
                (Style::new().dim().apply_to("·"), "No")
            };

            if dumb {
                // Forward-only: print answer below the options, no clearing.
                term.write_line(&format!("{}{} {}", pad, icon, answer_label))
                    .map_err(BivvyError::Io)?;
            } else {
                // Clear option lines
                term.clear_last_lines(options.len())
                    .map_err(BivvyError::Io)?;
                // Clear the prompt question line
                term.clear_last_lines(1).map_err(BivvyError::Io)?;
                // Re-print prompt question, then answer on a new line with indicator
                term.write_line(&prompt.question).map_err(BivvyError::Io)?;
                term.write_line(&format!("{}{} {}", pad, icon, answer_label))
                    .map_err(BivvyError::Io)?;
            }

            // _cursor_guard is dropped here, restoring the cursor.
            return Ok(PromptResult::String(options[idx].value.clone()));
        }

        if !dumb {
            // Clear option lines for redraw (cursor movement not supported on dumb)
            term.clear_last_lines(options.len())
                .map_err(BivvyError::Io)?;

            // Redraw option lines with updated selection
            for (i, opt) in options.iter().enumerate() {
                let line = if i == sel {
                    format!(
                        "{}{} {}",
                        pad,
                        active_prefix.apply_to("›"),
                        active_style.apply_to(&opt.label)
                    )
                } else {
                    format!(
                        "{}{} {}",
                        pad,
                        inactive_prefix.apply_to("·"),
                        inactive_style.apply_to(&opt.label)
                    )
                };
                term.write_line(&line).map_err(BivvyError::Io)?;
            }
            term.flush().map_err(BivvyError::Io)?;
        }
    }
}

fn prompt_multiselect(
    prompt: &Prompt,
    options: &[PromptOption],
    term: &Term,
) -> Result<PromptResult> {
    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();

    let default_values: Vec<&str> = prompt
        .default
        .as_deref()
        .map(|d| d.split(',').collect())
        .unwrap_or_default();
    let defaults: Vec<bool> = options
        .iter()
        .map(|o| default_values.contains(&o.value.as_str()))
        .collect();

    let multiselect_theme = ColorfulTheme {
        prompt_suffix: style("".to_string()),
        ..prompt_theme()
    };

    // Print prompt question and hint text for keyboard controls
    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
    term.write_line(&format!(
        "{}",
        style("[space] toggle · [a] toggle all · [enter] confirm").dim()
    ))
    .map_err(BivvyError::Io)?;

    let selections = match MultiSelect::with_theme(&multiselect_theme)
        .items(&labels)
        .defaults(&defaults)
        .interact_on(term)
    {
        Ok(sel) => sel,
        Err(e) if is_dialoguer_eof(&e) => defaults
            .iter()
            .enumerate()
            .filter_map(|(i, &on)| if on { Some(i) } else { None })
            .collect(),
        Err(e) => return Err(map_dialoguer_err(e)),
    };

    let values: Vec<String> = selections
        .iter()
        .map(|&i| options[i].value.clone())
        .collect();

    Ok(PromptResult::Strings(values))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn make_prompt(key: &str, prompt_type: PromptType, default: Option<&str>) -> Prompt {
        Prompt {
            key: key.to_string(),
            question: "Test question?".to_string(),
            prompt_type,
            default: default.map(String::from),
        }
    }

    #[test]
    fn prompt_creation() {
        let prompt = make_prompt("test", PromptType::Input, Some("default"));
        assert_eq!(prompt.key, "test");
        assert_eq!(prompt.default, Some("default".to_string()));
    }

    #[test]
    fn prompt_type_confirm_creation() {
        let prompt = make_prompt("confirm", PromptType::Confirm, None);
        assert!(matches!(prompt.prompt_type, PromptType::Confirm));
    }

    #[test]
    fn prompt_type_select_with_options() {
        let options = vec![
            PromptOption {
                label: "Option A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "Option B".to_string(),
                value: "b".to_string(),
            },
        ];
        let prompt = make_prompt(
            "select",
            PromptType::Select {
                options: options.clone(),
            },
            None,
        );
        if let PromptType::Select { options: stored } = prompt.prompt_type {
            assert_eq!(stored.len(), 2);
            assert_eq!(stored[0].value, "a");
        } else {
            panic!("Expected Select variant");
        }
    }

    #[test]
    fn prompt_type_multiselect_with_options() {
        let options = vec![PromptOption {
            label: "Feature 1".to_string(),
            value: "f1".to_string(),
        }];
        let prompt = make_prompt(
            "multi",
            PromptType::MultiSelect {
                options: options.clone(),
            },
            None,
        );
        if let PromptType::MultiSelect { options: stored } = prompt.prompt_type {
            assert_eq!(stored.len(), 1);
        } else {
            panic!("Expected MultiSelect variant");
        }
    }

    #[test]
    fn is_yes_no_returns_true_for_yes_no_options() {
        let options = vec![
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
        ];
        assert!(is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_true_regardless_of_order() {
        let options = vec![
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
        ];
        assert!(is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_false_for_other_options() {
        let options = vec![
            PromptOption {
                label: "Option A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "Option B".to_string(),
                value: "b".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

    #[test]
    fn is_yes_no_returns_false_for_more_than_two() {
        let options = vec![
            PromptOption {
                label: "Yes".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No".to_string(),
                value: "no".to_string(),
            },
            PromptOption {
                label: "Maybe".to_string(),
                value: "maybe".to_string(),
            },
        ];
        assert!(!is_yes_no(&options));
    }

    #[test]
    fn select_theme_creates_without_panic() {
        let theme = select_theme();
        // Verify the theme object can be used (smoke test)
        drop(theme);
    }

    #[test]
    fn cursor_guard_restores_on_drop() {
        // CursorGuard::new requires a real terminal for hide_cursor(),
        // but we can verify the struct compiles and the Drop impl exists
        // by constructing with Term::stdout() in a non-panicking context.
        // On non-TTY (CI), hide_cursor is a no-op that still succeeds.
        let term = Term::stdout();
        // If hide_cursor succeeds, guard will restore on drop.
        // If it fails (no TTY), that's fine — the guard pattern is still valid.
        let guard_result = CursorGuard::new(&term);
        if let Ok(guard) = guard_result {
            drop(guard);
            // After drop, cursor should be visible again (no-op on non-TTY).
        }
    }

    // -----------------------------------------------------------------------
    // SIGTTOU/SIGTTIN regression tests — DO NOT REMOVE
    //
    // These tests exist because `prompt_yes_no` calls `term.read_key()`
    // directly, which invokes `tcsetattr` (SIGTTOU) and reads from the
    // terminal fd (SIGTTIN). When bivvy is not the terminal's foreground
    // process group (e.g., `cargo run`), this triggers suspension.
    //
    // The SIGTTOU signal is ignored in main.rs, but these tests verify:
    //   1. The prompt code doesn't panic or crash on non-TTY
    //   2. Yes/no and multi-option selects produce consistent error behavior
    //
    // History: These tests were originally added in commit 09d5292, then
    // removed in commit 520c90c when the custom yes/no prompt was
    // reintroduced. Removing them allowed the SIGTTOU regression to go
    // undetected. They are restored here to prevent that from happening
    // again.
    //
    // If you need to change prompt_yes_no's output formatting, do so
    // WITHOUT removing these tests. The custom yes/no prompt (y/n
    // shortcuts, cursor guard, styled indicators) is a legitimate
    // customization — but it MUST coexist with SIGTTOU safety.
    // -----------------------------------------------------------------------

    #[test]
    fn yes_no_prompt_does_not_crash_on_non_tty() {
        // Term::stdout() in test context is piped (non-TTY) because
        // cargo test captures stdout. On non-TTY, prompt_select falls
        // through to dialoguer's Select, which hits EOF. With EOF
        // handling, this returns the default value instead of crashing.
        let term = Term::stdout();
        if term.is_term() {
            return; // Skip under --nocapture with real TTY
        }

        let options = vec![
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
        ];
        let prompt = make_prompt(
            "rerun_step",
            PromptType::Select {
                options: options.clone(),
            },
            Some("yes"),
        );

        // Call the REAL prompt code, not MockUI.
        // No SIGTTOU, no panic, no crash — returns default on EOF.
        let result = prompt_select(&prompt, &options, &term);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_string(), "yes");
    }

    #[test]
    fn yes_no_and_multi_option_selects_handle_eof_consistently() {
        // Verify that yes/no prompts and multi-option selects both
        // return defaults on non-TTY (EOF). Neither should panic.
        let term = Term::stdout();
        if term.is_term() {
            return; // Skip under --nocapture with real TTY
        }

        // 2-option yes/no (non-TTY falls through to dialoguer Select)
        let yn_options = vec![
            PromptOption {
                label: "Yes (y)".to_string(),
                value: "yes".to_string(),
            },
            PromptOption {
                label: "No (n)".to_string(),
                value: "no".to_string(),
            },
        ];
        let yn_prompt = make_prompt(
            "yn",
            PromptType::Select {
                options: yn_options.clone(),
            },
            Some("yes"),
        );

        // 3-option select (goes through dialoguer's Select)
        let multi_options = vec![
            PromptOption {
                label: "A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "B".to_string(),
                value: "b".to_string(),
            },
            PromptOption {
                label: "C".to_string(),
                value: "c".to_string(),
            },
        ];
        let multi_prompt = make_prompt(
            "multi",
            PromptType::Select {
                options: multi_options.clone(),
            },
            Some("a"),
        );

        // Both return defaults on EOF — neither should panic or crash.
        let result_yn = prompt_select(&yn_prompt, &yn_options, &term);
        let result_multi = prompt_select(&multi_prompt, &multi_options, &term);

        assert!(result_yn.is_ok(), "yes/no should return default on EOF");
        assert_eq!(result_yn.unwrap().as_string(), "yes");
        assert!(result_multi.is_ok(), "multi should return default on EOF");
        assert_eq!(result_multi.unwrap().as_string(), "a");
    }

    // -----------------------------------------------------------------------
    // Ctrl+D / EOF handling tests
    // -----------------------------------------------------------------------

    #[test]
    fn is_eof_detects_unexpected_eof() {
        let err = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "end of file");
        assert!(is_eof(&err));
    }

    #[test]
    fn is_eof_rejects_other_errors() {
        let err = std::io::Error::new(std::io::ErrorKind::NotFound, "not found");
        assert!(!is_eof(&err));
    }

    #[test]
    fn ctrl_d_byte_is_recognized() {
        // Ctrl+D in raw mode sends byte 0x04. Verify the constant we
        // use in match arms is correct.
        assert_eq!(CTRL_D, '\x04');
    }

    #[test]
    fn debug_dialoguer_error_kind() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let result = dialoguer::Confirm::new()
            .with_prompt("test?")
            .default(true)
            .interact_on(&term);
        match result {
            Ok(v) => eprintln!("OK: {}", v),
            Err(e) => {
                let io_err: std::io::Error = e.into();
                eprintln!("Error kind: {:?}", io_err.kind());
                eprintln!("Error msg: {}", io_err);
                eprintln!("Is EOF: {}", io_err.kind() == std::io::ErrorKind::UnexpectedEof);
            }
        }
    }

    #[test]
    fn prompt_confirm_returns_default_on_eof() {
        // Simulate EOF by using a non-TTY term. On non-TTY, read_key
        // returns Key::Unknown which dialoguer can't handle, producing
        // an error. With our EOF handling, this should fall back to the
        // default value instead of panicking.
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let prompt = make_prompt("confirm_eof", PromptType::Confirm, Some("true"));
        let result = prompt_confirm(&prompt, &term);
        // Should return the default (true) rather than an error.
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_bool(), Some(true));
    }

    #[test]
    fn prompt_confirm_returns_default_false_on_eof() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let prompt = make_prompt("confirm_eof", PromptType::Confirm, Some("false"));
        let result = prompt_confirm(&prompt, &term);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_bool(), Some(false));
    }

    #[test]
    fn prompt_input_returns_default_on_eof() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let prompt = make_prompt("input_eof", PromptType::Input, Some("fallback"));
        let result = prompt_input(&prompt, &term);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_string(), "fallback");
    }

    #[test]
    fn prompt_input_errors_on_eof_without_default() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let prompt = make_prompt("input_eof", PromptType::Input, None);
        let result = prompt_input(&prompt, &term);
        assert!(result.is_err());
    }

    #[test]
    fn prompt_select_returns_default_on_eof() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let options = vec![
            PromptOption {
                label: "A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "B".to_string(),
                value: "b".to_string(),
            },
            PromptOption {
                label: "C".to_string(),
                value: "c".to_string(),
            },
        ];
        let prompt = make_prompt(
            "select_eof",
            PromptType::Select {
                options: options.clone(),
            },
            Some("b"),
        );
        let result = prompt_select(&prompt, &options, &term);
        assert!(result.is_ok());
        assert_eq!(result.unwrap().as_string(), "b");
    }

    #[test]
    fn prompt_multiselect_returns_defaults_on_eof() {
        let term = Term::stdout();
        if term.is_term() {
            return;
        }
        let options = vec![
            PromptOption {
                label: "X".to_string(),
                value: "x".to_string(),
            },
            PromptOption {
                label: "Y".to_string(),
                value: "y".to_string(),
            },
