        );

        // 3-option select (goes through dialoguer's Select)
        let multi_options = vec![
            PromptOption {
                label: "A".to_string(),
                value: "a".to_string(),
            },
            PromptOption {
                label: "B".to_string(),
                value: "b".to_string(),
            },
            PromptOption {
                label: "C".to_string(),
                value: "c".to_string(),
            },
        ];
        let multi_prompt = make_prompt(
            "multi",
            PromptType::Select {
                options: multi_options.clone(),
            },
            Some("a"),
        );

        // Both return defaults on EOF — neither should panic or crash.
        let result_yn = prompt_select(&yn_prompt, &yn_options, &term);
        let result_multi = prompt_select(&multi_prompt, &multi_options, &term);

        assert!(result_yn.is_ok(), "yes/no should return default on EOF");
        assert_eq!(result_yn.unwrap().as_string(), "yes");
        assert!(result_multi.is_ok(), "multi should return default on EOF");
        assert_eq!(result_multi.unwrap().as_string(), "a");
    }

